const carvingOriginals=["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"];function replaceCarvingFaces(shop, bench) {
  const faces = [];
  for (const group of [...bench.children, ...shop.children.filter(g => g.position.x === -3.2)]) {
    const face = group.children.find(m => m.isMesh && m.geometry.type === 'PlaneGeometry' && m.material.map);
    if (face) faces.push(face);
  }
  faces.forEach((face, i) => {
    const img = new Image();
    img.onload = () => {
      const c = document.createElement('canvas');
      c.width = img.height; c.height = img.width;
      const ctx = c.getContext('2d');
      ctx.translate(c.width,c.height); ctx.rotate(-Math.PI/2); ctx.scale(1,-1);
      ctx.drawImage(img,0,0);
      const pixels=ctx.getImageData(0,0,c.width,c.height), p=pixels.data;
      const levels=new Uint8Array(p.length/4), histogram=new Uint32Array(256);
      for(let j=0;j<levels.length;j++){const k=j*4;levels[j]=Math.max(p[k],p[k+1],p[k+2]);histogram[levels[j]]++}
      let paper=0,sum=0;
      while(paper<255 && (sum+=histogram[paper])<levels.length*.8)paper++;
      for(let j=0;j<levels.length;j++){
        const light=Math.min(1,levels[j]/Math.max(1,paper)),k=j*4;
        p[k]=42+135*light;p[k+1]=27+91*light;p[k+2]=19+53*light;
      }
      ctx.putImageData(pixels,0,0);
      const texture=new THREE.CanvasTexture(c);texture.colorSpace=THREE.SRGBColorSpace;
      face.material.map=texture;face.material.needsUpdate=true;
    };
    img.src=carvingOriginals[i%carvingOriginals.length];
  });
}